param([string]$SavePath=(Join-Path $PSScriptRoot '../../.local-research/runtime/profile-20261102/Saves/biomes-stopped-b.rws'))
# Read-only world metadata; no assembly loading and no tile-array decoding.
$ErrorActionPreference='Stop'
$s=[xml](Get-Content -Raw -LiteralPath $SavePath)
$info=$s.SelectSingleNode('//world/info');$grid=$s.SelectSingleNode('//world/grid')
if(!$info -or !$grid){throw 'Expected world/info and world/grid in this original save.'}
function ShaText([string]$value){$h=[Security.Cryptography.SHA256]::Create();try{return [Convert]::ToHexString($h.ComputeHash([Text.Encoding]::UTF8.GetBytes($value))).ToLowerInvariant()}finally{$h.Dispose()}}
[ordered]@{file=(Split-Path -Leaf $SavePath);sha256=(Get-FileHash -LiteralPath $SavePath -Algorithm SHA256).Hash.ToLowerInvariant();bytes=(Get-Item -LiteralPath $SavePath).Length;version=$s.SelectSingleNode('//meta/gameVersion').InnerText;mods=@($s.SelectNodes('//meta/modIds/li')|ForEach-Object{$_.InnerText});tick=[int]$s.SelectSingleNode('//tickManager/ticksGame').InnerText;world_info=[ordered]@{name=[string]$info.name;seed=[string]$info.seedString;coverage=[double]::Parse($info.planetCoverage,[Globalization.CultureInfo]::InvariantCulture);persistent_random_value=[int]$info.persistentRandomValue;rainfall=[string]$info.overallRainfall;temperature=[string]$info.overallTemperature;initial_map_size=[string]$info.initialMapSize;factions=@($info.SelectNodes('factions/li')|ForEach-Object{$_.InnerText});present_fields=@($info.ChildNodes|ForEach-Object{$_.LocalName})};world_info_xml_sha256=(ShaText $info.OuterXml);world_grid_xml_sha256=(ShaText $grid.OuterXml);grid_present_fields=@($grid.ChildNodes|ForEach-Object{$_.LocalName});tile_arrays_decoded=$false;scope='World metadata only. Individual tile values are UI observations, not inferred from missing XPath matches.'}|ConvertTo-Json -Depth 12
